#include "kernel.h"
#include "object.h"
#include "gui.h"
#include "net.h"
Object objects[OBJECTS];static u32 generation,cookie;
int object_new(u32 type,int value){for(int i=0;i<OBJECTS;i++)if(!objects[i].refs){if(generation>=0x7fffffu)return S_LIMIT;u32 g=++generation;objects[i]=(Object){g,1,type,value};return i;}return S_LIMIT;}
int handle_open(Handle *table,int index,u32 rights){if(index<0||index>=OBJECTS||!objects[index].refs)return S_BADHANDLE;for(int i=0;i<HANDLES;i++)if(!table[i].generation){if(cookie>=0x7fffffu)return S_LIMIT;table[i]=(Handle){(u32)index,objects[index].generation,rights,++cookie};return (int)((cookie<<8)|(u32)(i+1));}return S_LIMIT;}
Object *handle_get(Handle *table,u32 h,u32 type,u32 rights){u32 slot=(h&255)-1;if(slot>=HANDLES)return 0;Handle *r=&table[slot];if(!r->generation||r->cookie!=(h>>8)||r->object>=OBJECTS||(r->rights&rights)!=rights)return 0;Object *o=&objects[r->object];return o->refs&&o->generation==r->generation&&o->type==type?o:0;}
int handle_close(Handle *table,u32 h){u32 slot=(h&255)-1;if(slot>=HANDLES)return S_BADHANDLE;Handle *r=&table[slot];if(!r->generation||r->cookie!=(h>>8))return S_BADHANDLE;Object *o=&objects[r->object];if(o->generation!=r->generation||!o->refs)return S_BADHANDLE;memset(r,0,sizeof(*r));if(!--o->refs){if(o->type==OBJ_WINDOW)gui_user_close(o->value);else if(o->type==OBJ_SOCKET)net_close(o->value);}return 0;}
int handle_duplicate(Handle *t,u32 h,u32 rights){u32 slot=(h&255)-1;if(slot>=HANDLES||!t[slot].generation||t[slot].cookie!=(h>>8)||!rights||(rights&~t[slot].rights))return S_BADHANDLE;Object *o=&objects[t[slot].object];if(!o->refs||o->generation!=t[slot].generation)return S_BADHANDLE;int result=handle_open(t,(int)t[slot].object,rights);if(result>=0)o->refs++;return result;}
void handles_close(Handle *t){for(u32 i=0;i<HANDLES;i++)if(t[i].generation)handle_close(t,(t[i].cookie<<8)|(i+1));}
void object_tests(void){Handle t[HANDLES];memset(t,0,sizeof(t));int o=object_new(OBJ_EVENT,0),h=handle_open(t,o,3);if(h<0||!handle_get(t,(u32)h,OBJ_EVENT,1)||handle_get(t,(u32)h,OBJ_WINDOW,1)||handle_get(t,(u32)h,OBJ_EVENT,4)||handle_close(t,(u32)h)||handle_get(t,(u32)h,OBJ_EVENT,1)||handle_close(t,(u32)h)!=S_BADHANDLE)panic("Handle validation",0,0);int b=object_new(OBJ_EVENT,1),k=handle_open(t,b,1);if(k==h||handle_get(t,(u32)h,OBJ_EVENT,1))panic("Stale handle",0,0);int duplicate=handle_duplicate(t,(u32)k,1);if(duplicate<0||objects[b].refs!=2||handle_duplicate(t,(u32)k,2)!=S_BADHANDLE)panic("Handle duplication rights",0,0);handle_close(t,(u32)k);int newer=handle_duplicate(t,(u32)duplicate,1);if(newer==k||handle_get(t,(u32)k,OBJ_EVENT,1))panic("Duplicated stale slot",0,0);handles_close(t);if(objects[b].refs)panic("Object reference release",0,0);debug("OBJECT handles rights/stale/release PASS\n");}
